menuitem.script:
			if (window.external.application.CurrentPointID != null && window.external.application.CurrentPointID != '')

			{

				var wmSingleWindow = 0; // single window mode

				var wmMultiWindow  = 1; // multi window mode

				var displayUrl = "sysProcedureExplorer?ProcedureName=" + encodeURIComponent(window.external.application.CurrentPointID);

				

				if (window.external.application.WindowMode === wmSingleWindow || window.external.application.IsOnTouchPanel) 

				{

					var ptSchematic    	= 0; // schematic popup type

					var offsetWidth    	= window.external.parentWindow.document.body.offsetWidth;

					var offsetHeight	= window.external.parentWindow.document.body.offsetHeight;

					var popupWidth 	   	= 650;

					var popupHeight    	= 700;

				

					var objHdxPopup = window.external.parentWindow.document.getElementById("HDXPopupBehavior");

					objHdxPopup.CreatePopupWindow3(displayUrl, (offsetWidth - popupWidth) / 2, (offsetHeight - popupHeight) / 2, popupWidth, popupHeight, ptSchematic, false, true);							

				} 

				else if (window.external.application.WindowMode === wmMultiWindow) 

				{

					window.external.application.currentpage = displayUrl;

				}       

			}

			

			window.external.CloseShortcutMenu();

			if (window.external.application.CurrentPointID == null)

				window.external.application.currentpage='sysCfgAlarmSuppression.htm';

			else

			{

				var pointName = String(window.external.application.CurrentPointID);

				window.external.application.currentpage='sysCfgAlarmSuppression.htm?PointName=' + pointName;

			}

			window.external.CloseShortcutMenu();

                     if (window.external.application.CurrentPointID != null && window.external.application.CurrentPointID != '')

                     {

                           var wmSingleWindow = 0; // single window mode

                           var wmMultiWindow  = 1; // multi window mode

                           var ptSchematic    = 0;    // schematic popup type

                           var ptFaceplate    = 1;    // faceplate popup type

                           var displayName = 'sysalarmhelp?PointName=' + String(window.external.application.CurrentPointID);

                           if (window.external.application.WindowMode === wmSingleWindow) {

                                  window.external.application.InvokePopup2(displayName, 0, 0, ptSchematic, false);

                           } else if (window.external.application.WindowMode === wmMultiWindow) {

                                  window.external.application.currentpage = displayName;

                           }

                     }

                     window.external.CloseShortcutMenu();
